head.script:
scwin.checkoutInterval = null;
scwin.now = new Date();

scwin.onpageload = function () {
    scwin.checkoutInterval = setInterval(function () {
        const now = new Date();

        let hour = now.getHours();
        const minute = String(now.getMinutes()).padStart(2, '0');
        const second = String(now.getSeconds()).padStart(2, '0');

        const ampm = hour < 12 ? '오전' : '오후';
        hour = hour % 12;
        if (hour === 0) hour = 12;
        const hourStr = String(hour).padStart(2, '0');

        const currentTimeStr = `${ampm} ${hourStr}:${minute}:${second}에 퇴근처리 됩니다.`;

        spn_checkoutMsg.setValue(currentTimeStr);
    }, 1000);

    spn_date.setValue(scwin.currentDate());
};


scwin.currentDate = function () {
    const now = scwin.now;

    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');

    let hour = now.getHours();
    const minute = String(now.getMinutes()).padStart(2, '0');
    const second = String(now.getSeconds()).padStart(2, '0');

    const ampm = hour < 12 ? '오전' : '오후';
    hour = hour % 12;
    if (hour === 0) hour = 12;

    const hourStr = String(hour).padStart(2, '0');
    return `${year}년 ${month}월 ${day}일 ${ampm} ${hourStr}:${minute}:${second}`;
};

scwin.confirmBtn_onclick = function (e) {
    clearInterval(scwin.checkoutInterval);
    $p.closePopup();
};
